def detect(view):
    import re
    # question cue: the rule of patches_ccdiag/R3_H2.py e1_pre_complete, verbatim
    task = re.sub(r'"[^"]*"|“[^”]*”|(?<![A-Za-z])\'[^\']{1,200}\'(?![A-Za-z])', " ", view["task"] or "")
    cue = re.search(r"\?|\b(tell me|let me know|give me|find out|how many|how much|how long|what is|what are|what was|what's|which one)\b", task, re.I) \
        or re.match(r"\s*(what|which|who|whom|when|where|how|is|are|do|does|did|can|could|should|was|were)\b", task, re.I)
    if cue:
        return False
    code = view["pending"] or ""
    for m in re.finditer(r"apis\.supervisor\.complete_task\s*\(", code):
        args, cur, depth, q, esc = [], "", 0, None, False
        for ch in code[m.end():]:
            if q:
                cur += ch
                if esc: esc = False
                elif ch == "\\": esc = True
                elif ch == q: q = None
                continue
            if ch in "'\"":
                q = ch
            elif ch in "([{":
                depth += 1
            elif ch in ")]}":
                if depth == 0:
                    break
                depth -= 1
            elif ch == "," and depth == 0:
                args.append(cur.strip()); cur = ""
                continue
            cur += ch
        args = [a for a in args + [cur.strip()] if a]
        ans = None
        for a in args:
            km = re.match(r"answer\s*=(?!=)\s*(.*)$", a, re.S)
            if km: ans = km.group(1).strip()
        pos = [a for a in args if not re.match(r"[A-Za-z_]\w*\s*=(?!=)", a)]
        if ans is None and pos: ans = pos[0]
        if ans is not None and ans != "None":
            return True
    return False
